    cursor = conn.cursor()

    sql_query = "SELECT * FROM users WHERE name = ?"
    cursor.execute(sql_query, (query,))

    results = cursor.fetchall()
    conn.close()
    return str(results)

if __name__ == '__main__':
    app.run(debug=True)
